from docx.shared import Inches, Pt
from report_builder_utils import add_styled_heading, add_p, add_bullet, add_table_data

def build_chapter_2(doc):
    add_styled_heading(doc, "CHAPTER 2: LITERATURE REVIEW / EXISTING SYSTEM", level=1)
    
    add_styled_heading(doc, "2.1 Existing System Study and Theoretical Foundations", level=2)
    add_p(doc, "The evolution of agricultural decision-support systems over the past four decades reflects broader paradigm shifts in computational intelligence. Historically, agricultural recommendation originated in the 1980s and 1990s through expert systems and fuzzy inference engines. Early systems encoded human agronomist heuristics into deterministic 'if-then' rule bases. While these systems possessed transparent interpretability, they suffered from catastrophic brittleness: manual rule curation was labor-intensive, unable to scale across heterogeneous geographic regions, and incapable of reconciling continuous, conflicting multi-variable interactions (such as the non-linear interplay between high soil nitrogen and delayed reproductive flowering under drought stress).")

    add_styled_heading(doc, "2.1.1 Conventional Machine Learning Paradigms", level=3)
    add_p(doc, "With the advent of digital soil testing and agricultural data repositories, machine learning transformed crop recommendation into a supervised multi-class classification problem. Given a vector of soil nutrient and atmospheric observations x ∈ R^F, an algorithm learns a mapping function F(x) → y to predict the optimal crop cultivar y ∈ {c_1, ..., c_C}. Across the academic literature, several algorithmic families have formed the benchmark baseline:")

    add_bullet(doc, "Linear & Logistic Classifiers: ", "Logistic regression establishes linear decision hyperplanes across feature space. While computationally lightweight and mathematically tractable, logistic models assume that classes are linearly separable and that input features exert strictly monotonic independent effects on log-odds. In biological crop growth, however, nutrient response curves follow non-linear Mitscherlich-Baule yield laws where marginal returns diminish and nutrient toxicities arise at extreme thresholds, rendering linear classifiers inadequate.")
    add_bullet(doc, "Decision Trees (CART): ", "The Classification and Regression Tree (CART) framework partitions feature space into hyper-rectangular regions via recursive orthogonal splitting. At each internal node, CART selects the feature and split threshold that maximizes Gini impurity reduction or Shannon information gain. While single decision trees mimic human agronomic decision flowcharts, they exhibit notoriously high variance: minor perturbations in training soil samples induce radical structural changes in tree depth and split order, leading to severe overfitting.")
    add_bullet(doc, "Random Forests (Bagging): ", "Breiman's Random Forest mitigates the high variance of individual decision trees through bootstrap aggregation (bagging) and random feature subspace selection. By training an ensemble of B de-correlated decision trees across bootstrap samples of the training set and aggregating their probabilistic outputs via uniform majority voting, Random Forests achieve strong variance reduction and robust boundary regularization on tabular data. However, standard Random Forests cannot model continuous feature interactions and possess no mechanism to inject prior biological domain knowledge.")
    add_bullet(doc, "Gradient-Boosted Decision Trees (XGBoost): ", "Introduced by Chen and Guestrin, XGBoost revolutionized tabular machine learning through additive sequential tree boosting. Unlike bagging, where trees are trained independently in parallel, gradient boosting trains trees iteratively, where each subsequent tree fits the negative gradient (pseudo-residuals) of the loss function with respect to the ensemble's previous predictions. Incorporating second-order Taylor expansions of the loss function, explicit L1 (Lasso) and L2 (Ridge) leaf weight regularization, and sparsity-aware split finding, XGBoost constructs tight, highly non-linear decision partitions. Nevertheless, XGBoost models space using step-wise discontinuous functions, cannot extrapolate beyond training extremes, and treats all agricultural features as agnostic, independent numerical axes.")

    add_styled_heading(doc, "2.1.2 Deep Tabular Transformers", level=3)
    add_p(doc, "While deep learning revolutionized computer vision (via CNNs) and natural language processing (via Transformers), its application to structured tabular data long lagged behind gradient-boosted trees. Tabular data lacks the spatial locality of pixels or the sequential grammar of text; columns represent heterogeneous continuous and categorical variables with varying physical distributions.")
    add_p(doc, "Recently, Gorishniy et al. (2021) introduced the Feature Tokenizer Transformer (FT-Transformer), adapting multi-head self-attention directly to tabular domains. FT-Transformer projects every continuous numerical feature into an individual high-dimensional token vector via learned affine transformations. A learnable [CLS] token is prepended to the token sequence, which then passes through stacked Transformer encoder layers. Multi-head self-attention computes dot-product similarity across all feature tokens simultaneously, dynamically weighting pairwise and high-order cross-feature relationships. While FT-Transformer represents a major advance for tabular deep learning, empirical research by Grinsztajn et al. (NeurIPS 2022) revealed that pure tabular transformers require extensive parameter counts, suffer from slow optimization, and struggle to establish sharp localized decision partitions compared to tree ensembles on small-to-medium tabular datasets.")

    add_styled_heading(doc, "2.1.3 Theory-Guided Data Science and Knowledge-Guided Machine Learning", level=3)
    add_p(doc, "A critical emerging paradigm in computational intelligence is Theory-Guided Data Science (TGDS), pioneered by Karpatne et al. (2017). TGDS argues that purely data-driven models, regardless of depth or capacity, are prone to learning non-physical or biologically impossible relationships when operating in complex scientific domains. By incorporating established scientific laws—such as conservation of mass, energy balance, or thermodynamic limits—into the learning process, models gain improved generalizability, physically consistent latent representations, and resilience against sampling bias.")
    add_p(doc, "In agricultural modeling, Yang et al. (2023) demonstrated the efficacy of Knowledge-Guided Machine Learning Data Assimilation (KGML-DA) for agroecosystem simulation, showing that coupling neural networks with biophysical crop growth models significantly improved multi-year regional yield forecasting under extreme climatic anomalies. However, existing knowledge-guided implementations have focused predominantly on continuous physical differential equations in hydrology and climate simulation. Formalizing discrete agronomic crop suitability compendiums (such as FAO and ICAR ecological matrices) and injecting them into deep tabular attention graphs for multi-class cultivar recommendation remains an unexplored research frontier that this project directly investigates.")

    add_styled_heading(doc, "2.1.4 Explainability, Uncertainty, and Trustworthiness in Precision Agriculture", level=3)
    add_p(doc, "Trustworthy Artificial Intelligence requires that algorithmic predictions be explainable, robust, and uncertainty-aware. In agricultural decision support, explainability is typically tackled post-hoc. Lundberg and Lee (2017) formalized SHAP (SHapley Additive exPlanations), an axiomatic framework grounded in cooperative game theory. TreeSHAP computes exact Shapley values for tree ensembles in polynomial time, quantifying the marginal contribution of each agricultural feature toward shifting model output from a base expected value to a specific crop prediction.")
    add_p(doc, "Simultaneously, evaluating predictive uncertainty is essential in high-stakes environments where crop recommendations govern substantial capital expenditures. Gal and Ghahramani (2016) demonstrated that applying dropout during inference across M stochastic forward passes acts as a mathematically rigorous Bayesian approximation of a Gaussian process. Monte Carlo (MC) Dropout captures epistemic model uncertainty by measuring the variance across stochastic passes. Furthermore, modern neural calibration research by Guo et al. (2017) demonstrated that classification accuracy does not guarantee well-calibrated posterior probabilities. Evaluating Expected Calibration Error (ECE), Brier Score, and Negative Log-Likelihood (NLL) is critical for determining whether confidence scores faithfully reflect empirical accuracy.")

    add_styled_heading(doc, "2.2 Review of Existing Research Work", level=2)
    add_p(doc, "Table 2.1 presents a comprehensive comparative synthesis of recent peer-reviewed publications across agricultural recommendation, tabular transformers, knowledge-guided machine learning, explainability, and uncertainty estimation:")

    t21_headers = ["Author(s) & Year", "Methodology & Focus", "Dataset & Scope", "Major Empirical Findings", "Critical Limitations Addressed in Our Work"]
    t21_rows = [
        ["Singhal et al. (2025) [12]", "Comprehensive survey of AI & IoT crop recommendation systems", "Regional multi-source agricultural datasets", "Tree ensembles achieve high baseline accuracy; IoT sensor integration is expanding", "Omits explicit biological domain knowledge; completely lacks sensor noise stress-testing"],
        ["Mancer et al. (2025) [13]", "Systematic literature review of crop recommendation for Agriculture 4.0", "Sensor telemetry in smart farm environments", "Edge AI faces computational bottlenecks; heavy DL models cannot execute on field microcontrollers", "Focuses exclusively on cloud architectures; lacks real-time early-exit latency optimization"],
        ["SivaGanesh et al. (2026) [14]", "Comparative evaluation of ML models for precision agriculture", "Soil N-P-K, pH, and climatic attributes", "Random Forest and XGBoost consistently outperform linear baselines and shallow neural networks", "Outputs are deterministic; models lack uncertainty quantification and provide no safety alerts"],
        ["Gamya et al. (2025) [15]", "Comparative analysis of ML algorithms for crop recommendation", "2,200-sample balanced benchmark dataset", "Ensemble tree models exceed 99% accuracy under clean laboratory evaluation splits", "Evaluates only clean, complete test sets; ignores sensor faults, missing values, and range shifts"],
        ["Gorishniy et al. (2021) [5]", "Feature Tokenizer Transformer (FT-Transformer) for tabular data", "Standard tabular classification & regression benchmarks", "Self-attention matches or beats gradient-boosted trees on complex cross-feature interactions", "High parameter footprints; slow convergence and vulnerability to missing values on small datasets"],
        ["Karpatne et al. (2017) [7]", "Theory-Guided Data Science (TGDS) conceptual paradigm", "Scientific simulation benchmarks in hydrology and climate", "Injecting scientific domain laws into neural losses enforces physically consistent representations", "Confined to continuous physics differential equations; unadapted to discrete crop matrices"],
        ["Yang et al. (2023) [8]", "Knowledge-guided machine learning data assimilation (KGML-DA)", "US Midwest regional agroecosystem field telemetry", "Hybrid domain models generalize significantly better across anomalous, unseen climatic years", "Targeted strictly toward continuous crop yield forecasting rather than discrete crop selection"],
        ["Tharun et al. (2026) [20]", "Comparative analysis of RF, SVM, and XGBoost for crop recommendation", "Soil nutrient and environmental telemetry", "XGBoost achieves superior discriminative accuracy due to gradient pseudo-residual optimization", "Tree models partition space into rigid step functions and fail under out-of-distribution shifts"],
        ["Lundberg & Lee (2017) [9]", "TreeSHAP unified game-theoretic feature attribution framework", "Benchmark tabular, image, and text classification corpora", "TreeSHAP computes exact Shapley attributions in polynomial time, guaranteeing local accuracy", "Additive scores alone do not evaluate whether distinct hybrid model branches capture unique signals"],
        ["Gal & Ghahramani (2016) [10]", "Dropout as a Bayesian approximation for neural uncertainty", "Deep neural networks across computer vision and tabular domains", "Performing M stochastic forward passes with active dropout reliably quantifies epistemic uncertainty", "Uncalibrated networks still yield overconfident incorrect labels unless gated with safety rules"],
        ["Guo et al. (2017) [11]", "On calibration of modern deep neural networks", "Modern deep networks (ResNets, DenseNets, Transformers)", "High classification accuracy frequently coexists with severe confidence miscalibration", "Evaluates vision and NLP tasks; unexamined in knowledge-guided hybrid tabular architectures"],
        ["Grinsztajn et al. (2022) [21]", "Why do tree-based models still outperform deep learning on tabular data?", "45 standardized tabular datasets from OpenML", "Tree ensembles outperform deep networks due to inductive bias toward axis-aligned decision steps", "Treats tree models and neural networks as competitors rather than integrating them into a hybrid"]
    ]
    add_table_data(doc, "Table 2.1: Systematic Review of Benchmark Agricultural Machine Learning Works", t21_headers, t21_rows, [Inches(1.2), Inches(1.5), Inches(1.3), Inches(1.6), Inches(1.6)])

    add_styled_heading(doc, "2.3 Review of Existing Tools and Technologies", level=2)
    add_p(doc, "Table 2.2 details the computational libraries, frameworks, and software tools employed in implementing the KG-Hybrid pipeline:")

    t22_headers = ["Software / Tool", "Exact Version", "Technical Function in Implementation", "Architectural Role & Justification"]
    t22_rows = [
        ["Python", "3.10+ / 3.12", "Core programming runtime environment", "High-performance scientific execution ecosystem supporting asynchronous IO and typing"],
        ["NumPy", "1.24.0+", "Vectorized array and matrix linear algebra", "Fast in-memory manipulation of leaf index vectors, suitability matrices, and perturbations"],
        ["Pandas", "2.0.0+", "Tabular dataset ingestion and preprocessing", "Data schema verification, stratified subset partitioning, and CSV serialization"],
        ["Scikit-Learn", "1.3.0+", "Data scaling, encoding, and classical baselines", "Guarantees strictly leak-free StandardScaler, LabelEncoder, and evaluations (LR, CART, RF)"],
        ["XGBoost", "1.7.6+ / 2.0+", "Gradient-boosted decision tree ensemble", "Fits 200 trees, extracts discrete leaf indices l ∈ Z^200, and acts as fast Stage 1 early exit"],
        ["PyTorch", "2.1.0+ / 2.13.0", "Deep neural network modeling framework", "Implements EmbeddingBag, FT-Transformer, gated fusion, autograd, and composite loss"],
        ["SHAP", "0.42.1+", "Game-theoretic model explainability engine", "Implements TreeExplainer to compute exact Shapley attributions for branch complementarity"],
        ["FastAPI", "0.100.0+", "Asynchronous REST API microservice", "Exposes high-throughput, non-blocking inference endpoints delivering structured JSON payloads"],
        ["Pydantic", "2.0+", "Data contract and schema validation", "Enforces strict type and physiological range boundaries on incoming IoT sensor measurements"],
        ["Uvicorn", "0.22.0+", "High-throughput ASGI production web server", "Serves the asynchronous FastAPI application with low worker latency and concurrency"],
        ["ONNX Runtime", "1.15.0+", "Open Neural Network Exchange serialization", "Cross-platform graph serialization for embedded microcontrollers and edge hardware"],
        ["TensorFlow Lite", "2.14.0+", "Edge mobile quantization and execution", "8-bit integer quantization pipeline for ultra-low-power microcontrollers and mobile Android apps"]
    ]
    add_table_data(doc, "Table 2.2: Tools and Technologies Used in the Project", t22_headers, t22_rows, [Inches(1.2), Inches(1.0), Inches(2.2), Inches(2.8)])

    add_styled_heading(doc, "2.4 Research Gaps and Opportunities for Innovation", level=2)
    add_p(doc, "Our critical analysis of the current literature reveals four pivotal research gaps that motivate the technical design of KG-Hybrid:")

    add_p(doc, "Research Gap 1: Absence of Explicit Biological Knowledge in Tabular Recommendation Models. Prevailing crop recommendation models operate in an agronomic vacuum. Standard architectures (Random Forest, XGBoost, TabNet) optimize purely against empirical statistical correlations present in historical samples. However, agricultural ecosystems are governed by definitive physiological boundaries codified by global institutions like the FAO and ICAR. A purely data-driven model trained on limited regional data can easily identify spurious statistical artifacts, generating crop recommendations that violate fundamental soil chemistry or thermal tolerance laws. Innovation in KG-Hybrid: We formalize a normalized 22 × 7 Agronomic Knowledge Matrix K from FAO/ICAR compendiums and inject it directly into the neural network via sample-conditioned feature gating and an additive fusion bias vector b_kg, grounding latent representations in verified agricultural science.")

    add_p(doc, "Research Gap 2: Siloed Architectural Paradigms (Trees vs. Transformers). Tabular machine learning has remained divided between two mutually exclusive paradigms: (1) Tree Ensembles (XGBoost, Random Forest), which excel at identifying localized, non-linear step-wise partition boundaries; and (2) Deep Attention Networks (FT-Transformer), which project features into continuous vector spaces to model global all-to-all cross-feature interactions. Existing studies treat these models as competitors. Innovation in KG-Hybrid: Rather than choosing between them, KG-Hybrid combines both. Branch A extracts XGBoost leaf embeddings (f_xgb ∈ R^128) while Branch B extracts FT-Transformer attention embeddings (f_ft ∈ R^64). These complementary representations are merged via dynamic gated fusion with stop-gradient regularization, with biological complementarity confirmed via Spearman rank correlation (ρ = 0.43).")

    add_p(doc, "Research Gap 3: Complete Evaluation Blindness to Sensor Degradation and Environmental Shifts. The overwhelming majority of published crop recommendation papers report performance exclusively on clean, complete, and perfectly balanced laboratory benchmark datasets. In real-world precision farming, IoT soil sensors and weather telemetry continuously experience: (a) Sensor hardware failure yielding missing readings; (b) Electronic noise and calibration drift; and (c) Out-of-distribution regional or seasonal shifts. When standard models encounter these perturbations, their accuracy collapses (e.g., XGBoost drops from 99.39% to 61.15% under 40% missing data). Innovation in KG-Hybrid: We subject the framework to controlled missing-feature dropout (20%, 40%, 60%), additive Gaussian noise (σ ≤ 0.3), and 1.5× out-of-distribution feature scaling. Pairing KG-Hybrid with a leak-free KNN (k=5) imputation module restores 40% missing-data accuracy to 82.73% (+35.70 pp over raw models), while retaining 89.21% accuracy under Gaussian noise (σ=0.2).")

    add_p(doc, "Research Gap 4: Impractical Inference Latency and Parameter Footprints on Edge Devices. Deploying high-capacity deep tabular networks (>15M parameters) in rural farming environments is impractical due to hardware limitations (low-cost Android phones, microcontrollers) and lack of reliable high-speed Internet connectivity. Running full neural forward passes (>100 ms) for every routine prediction wastes battery power and computational resources. Innovation in KG-Hybrid: We develop two practical edge optimizations: (1) Two-Stage Early-Exit Routing: Confident predictions (τ ≥ 0.90) exit immediately after the fast XGBoost stage, handling 96.36% of queries and cutting average latency from 115.54 ms to 5.99 ms (14× speedup) while sustaining 99.70% accuracy; (2) Lightweight Model Variant: Pruning the embedding dimension from 128 to 32 compresses the model by 74% (to 4.04M parameters), cutting standalone latency to 25.40 ms while maintaining 99.39% accuracy.")

    add_styled_heading(doc, "2.5 Formal Problem Statement and Research Contributions", level=2)
    add_p(doc, "Formal Problem Statement: Let x = [x_N, x_P, x_K, x_temp, x_humid, x_pH, x_rain]^T ∈ R^7 denote a standardized vector of agricultural measurements. The primary objective is to learn a parameterized mapping function F: R^7 → Y that maps the observation to the optimal crop category from C=22 candidates Y = {c_1, c_2, ..., c_22} under three strict operational constraints: (1) Agronomic Consistency: Latent representations must conform to codified biological crop suitability envelopes codified in knowledge matrix K ∈ R^(22x7); (2) Environmental Robustness: The model must degrade gracefully when inputs suffer from missing features (x_miss), Gaussian electronic noise (x + ε, where ε ~ N(0, σ^2)), or feature-range extrapolation (α x, where α > 1.0); (3) Trustworthiness and Operational Efficiency: Recommendations must be supported by verifiable feature attribution (TreeSHAP), empirical uncertainty bounds (Monte Carlo Dropout), and low-latency inference suitable for rural edge microcontrollers.")

    add_p(doc, "Primary Research Contributions:")
    add_bullet(doc, "1. Novel KGAAN Hybrid Architecture: ", "Engineered a dual-branch neural architecture combining discrete leaf-node embeddings from a frozen XGBoost ensemble (T=200 trees) with continuous multi-head self-attention tokens from a 4-layer FT-Transformer.")
    add_bullet(doc, "2. Explicit Agronomic Prior Integration: ", "Formalized a normalized 22 × 7 FAO/ICAR suitability matrix K and designed a sample-conditioned knowledge feature gate and additive fusion bias b_kg, trained end-to-end with symmetric knowledge distillation and supervised contrastive losses.")
    add_bullet(doc, "3. Benchmark Superiority and Multi-Seed Validation: ", "Achieved 99.70% Accuracy, 99.70% Macro-F1, and 100.00% Top-3 Recall, matching Random Forest (99.70%) while outperforming baseline XGBoost (99.39%) and FT-Transformer (98.79%). A 7-variant ablation study isolated the contribution of each module, showing that removing auxiliary losses drops performance by -0.91 pp.")
    add_bullet(doc, "4. Fault-Tolerant Resilience Engineering: ", "Demonstrated that coupling KG-Hybrid with leak-free KNN (k=5) imputation restores 40% missing-data accuracy from 47.03% to 82.73%, while outperforming tree models under Gaussian noise (σ=0.2 at 89.21%) and 1.5× extrapolation (90.00%).")
    add_bullet(doc, "5. Trustworthy and Edge-Ready Serving Pipeline: ", "Integrated TreeSHAP explainability (confirming cross-branch complementarity at ρ=0.43) and Monte Carlo Dropout (M=10). Engineered a two-stage early-exit pipeline achieving a 14× latency reduction (to 5.99 ms) and a lightweight 4.04M-parameter variant, deployed via a production FastAPI microservice.")

